import { fetchKulturhusetEvents } from './src/sources/kulturhuset';
async function test() {
  console.log('Testing Kulturhuset pagination...');
  try {
    // Test first page with limit 5
    const page1 = await fetchKulturhusetEvents({ limit: 5, page: 0 });
    console.log('Page 1 (5 events):', page1.length);

    // Test first page with limit 100
    const page100 = await fetchKulturhusetEvents({ limit: 100, page: 0 });
    console.log('Page 1 (100 events):', page100.length);

    console.log('✅ Pagination works!');
  } catch (err) {
    console.error('Error:', err);
  }
}
test();
